#!/usr/bin/env bash
# 🧱 The cargo environment of builder.sh, run inside its namespace. SNIPPET is evaluated from the repo root.
tb="$R/.cache/b/t/m/r/699c2d5d27a9c904/toolchains/nightly-2026-07-20-x86_64-unknown-linux-gnu/bin"; bd="$(dirname "$(ls /home/deck/.cache/semio/runtimes/bun/*/bun | head -1)")"
    export PATH="$tb:$bd:$PATH" RUSTC="$tb/rustc" RUSTC_WRAPPER="" CARGO_HOME="$R/.cache/b/r/m/cargo/home" CARGO_TARGET_DIR=/tmp/build/t CARGO_BUILD_BUILD_DIR=/tmp/build/b CARGO_INCREMENTAL=0 CARGO_PROFILE_DEV_DEBUG=0 CARGO_PROFILE_TEST_DEBUG=0 CARGO_PROFILE_DEV_OPT_LEVEL="${CARGO_PROFILE_DEV_OPT_LEVEL:-1}" CARGO_PROFILE_TEST_OPT_LEVEL="${CARGO_PROFILE_TEST_OPT_LEVEL:-1}" CARGO_PROFILE_DEV_CODEGEN_UNITS=16 CARGO_PROFILE_TEST_CODEGEN_UNITS=16 CARGO_PROFILE_DEV_DEBUG_ASSERTIONS=true CARGO_PROFILE_DEV_OVERFLOW_CHECKS=true ZIG_GLOBAL_CACHE_DIR=/tmp/zig ZIG_LOCAL_CACHE_DIR=/tmp/zig-local TMPDIR=/tmp RUST_MIN_STACK=134217728 NATIVE_REPO_ROOT="$R" RUSTFLAGS="${RUSTFLAGS:--Z threads=1 -C linker-features=+lld -C link-self-contained=+linker -Z unstable-options -C embed-bitcode=no -C strip=symbols -Zembed-metadata=no}"
    if [ -n "${LANE_DIR:-}" ]; then mkdir -p "$LANE_DIR/t" "$LANE_DIR/b"; export CARGO_TARGET_DIR="$LANE_DIR/t" CARGO_BUILD_BUILD_DIR="$LANE_DIR/b"; fi
    cd "$R"; eval "$SNIPPET"
